try{const b=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));for(const[f,d,w]of [["League Spartan","",["300","500","700"]],["Fira Code","",["400","500"]]]){const u=b(d);for(const x of w)document.fonts.add(new FontFace(f,u,{weight:x,unicodeRange:'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD'}))}}catch(e){console.warn('fonts:',e)}